import type { Metadata } from "next";
import SitemapShell, {
  sitemapLinkClass,
  sitemapSectionHeadingClass,
} from "@/components/sitemap-directory/shell";
import { toursPageCount } from "@/components/sitemap-directory/tours-directory";
import {
  getSitemapDirectoryCategories,
  getSitemapDirectoryTours,
  groupCategoryPages,
} from "@/services/sitemap/directory";

export const revalidate = 86400;

export const metadata: Metadata = {
  title: "Sitemap - TravelShop Booking",
  description:
    "Browse all tours, destinations and tour categories on TravelShop Booking from a single directory.",
  alternates: {
    canonical: "https://travelshopbooking.com/sitemap",
  },
};

const quickLinks = [
  { href: "/", label: "Home" },
  { href: "/attractions", label: "Attractions" },
  { href: "/museums", label: "Museums" },
  { href: "/blog", label: "Blog" },
  { href: "/about-us", label: "About Us" },
  { href: "/contact-us", label: "Contact Us" },
  { href: "/help-center", label: "Help Center" },
];

export default async function SitemapHubPage() {
  const [categories, tours] = await Promise.all([
    getSitemapDirectoryCategories(),
    getSitemapDirectoryTours(1),
  ]);

  const destinationCount = categories.filter((c) => !c.paramCategory).length;
  const categoryPages = categories.filter((c) => c.paramCategory);
  const groupCount = groupCategoryPages(categories).length;
  const tourPages = toursPageCount(tours.total);

  const sections = [
    {
      href: "/sitemap/destinations",
      title: "Destinations",
      description: `${destinationCount.toLocaleString("en-US")} destination pages, organized by continent, country and city.`,
    },
    {
      href: "/sitemap/tour-categories",
      title: "Tour Categories",
      description: `${categoryPages.length.toLocaleString("en-US")} category pages across ${groupCount} travel themes.`,
    },
    {
      href: "/sitemap/tours",
      title: "Tours",
      description: `All ${tours.total.toLocaleString("en-US")} tours listed alphabetically across ${tourPages} pages.`,
    },
  ];

  return (
    <SitemapShell
      title="Sitemap"
      intro="A complete directory of TravelShop Booking — every destination, tour category and tour, one click away."
      crumbs={[{ pageTitle: "Sitemap", pageUrl: "/sitemap" }]}
    >
      <div className="tw-grid tw-grid-cols-1 md:tw-grid-cols-3 tw-gap-5">
        {sections.map((section) => (
          <a
            key={section.href}
            href={section.href}
            className="tw-block tw-rounded-2xl tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-6 hover:tw-border-[#854ec9] tw-transition-colors tw-no-underline"
          >
            <div className={sitemapSectionHeadingClass}>{section.title}</div>
            <p className="tw-mt-2 tw-mb-0 tw-text-[14px] tw-leading-[1.6] tw-text-[#5d556c]">
              {section.description}
            </p>
            <span className="tw-mt-4 tw-inline-block tw-text-[14px] tw-font-semibold tw-text-[#854ec9]">
              Browse {section.title} →
            </span>
          </a>
        ))}
      </div>

      <section className="tw-mt-12">
        <h2 className={sitemapSectionHeadingClass}>More from TravelShop Booking</h2>
        <ul className="tw-list-none tw-m-0 tw-mt-4 tw-p-0 tw-flex tw-flex-wrap tw-gap-x-8 tw-gap-y-2">
          {quickLinks.map((link) => (
            <li key={link.href}>
              <a href={link.href} className={sitemapLinkClass}>
                {link.label}
              </a>
            </li>
          ))}
        </ul>
      </section>
    </SitemapShell>
  );
}
